from datetime import date, timedelta


def business_day_count(start: str, end: str) -> int:
    d1 = date.fromisoformat(start)
    d2 = date.fromisoformat(end)
    if d1 > d2:
        return 0
    count = 0
    current = d1
    while current <= d2:
        if current.weekday() < 5:
            count += 1
        current += timedelta(days=1)
    return count

